evel":25,"sourceTextAlsoStatesGoodSpellsCasterLevel":26,"saveDc":"34 + spell level","sourceNote":"Obad-Hai is neutral and has no Good domain in Table 3-1, but the printed spell-like paragraph says ''except for good spells''; this apparent copy error is retained as source metadata rather than applied to generated domain membership."},"spellcasting":{"druidLevel":20,"clericLevel":20},"automaticActions":{"skills":["Craft (leatherworking)","Craft (pottery)","Craft (stoneworking)","Craft (woodworking)","Knowledge (arcana)","Knowledge (geography)","Knowledge (nature)","Knowledge (religion)"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":56,"attacks":{"defendingShockingStaff":"+58/+53/+48/+43, 1d6+12","speedIcyStaff":"+58/+53/+48/+43, 1d6+8"},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":26},"saves":{"fort":48,"ref":48,"will":55},"salientDivineAbilities":["Alter Size","Automatic Metamagic (quicken spell-like abilities)","Divine Blast","Divine Shield","Divine Fast Healing","Extra Domain (Air)","Extra Domain (Earth)","Speak with Creatures (animals)","Speak with Creatures (plants)"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level","sourceNote":"Avatar text says it loses Fire domain without Extra Domain (Fire), confirming the main deity possesses that salient ability."},"revision3_5":{"alignmentSubtypes":[],"damageReduction":"25/epic","fireResistance":20,"druidChanges":"Apply 3.5 wild shape, animal companion, wild empathy, and related class-feature terminology while preserving class level and divine block.","additionalOutsiderSkillPoints":true}}')
